import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerReels() {
    const navigate = useNavigate();
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);
    const [viewingReel, setViewingReel] = useState(null); // For viewing reel video only
    const [showVideoModal, setShowVideoModal] = useState(false); // For showing video in modal

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Initialize Remix Icons if available
        if (window.RemixIcon) {
            window.RemixIcon.init();
        }
        
        // Simulate loading reels with proper data
        setTimeout(() => {
            // Sample data with proper reel counts per product
            const sampleReels = [
                {
                    id: 1,
                    title: 'New Summer Collection',
                    product: 'Summer Dress',
                    category: 'Fashion',
                    status: 'approved',
                    views: 1250,
                    likes: 342,
                    date: '2023-06-15'
                },
                {
                    id: 2,
                    title: 'Winter Sale Announcement',
                    product: 'Winter Coat',
                    category: 'Seasonal',
                    status: 'pending',
                    views: 0,
                    likes: 0,
                    date: '2023-06-18'
                },
                {
                    id: 3,
                    title: 'New Arrival: Spring Shoes',
                    product: 'Spring Shoes',
                    category: 'Footwear',
                    status: 'approved',
                    views: 2100,
                    likes: 567,
                    date: '2023-06-10'
                },
                {
                    id: 4,
                    title: 'Summer Accessories',
                    product: 'Summer Dress', // Same product as reel 1
                    category: 'Fashion',
                    status: 'approved',
                    views: 750,
                    likes: 98,
                    date: '2023-06-22'
                }
            ];
            
            // Group reels by product and calculate counts
            const productMap = {};
            sampleReels.forEach(reel => {
                if (!productMap[reel.product]) {
                    productMap[reel.product] = {
                        ...reel,
                        reelCount: 0,
                        reels: []
                    };
                }
                productMap[reel.product].reelCount += 1;
                productMap[reel.product].reels.push(reel);
            });
            
            // Convert to array format for display
            const groupedReels = Object.values(productMap);
            setReels(groupedReels);
            setLoading(false);
        }, 500);
    }, []);

    const handleViewReelVideo = async (productId) => {
        // Find the product group
        const productGroup = reels.find(r => r.product === productId);
        if (productGroup) {
            setViewingReel(productGroup);
            setShowVideoModal(true);
        }
    };

    const handleEditReel = (reelId) => {
        // Navigate to the edit page
        navigate(`/studio/seller/upload/${reelId}`);
    };

    const handleDeleteReel = async (reelId) => {
        // Confirm deletion
        if (window.confirm('Are you sure you want to delete this reel? This action cannot be undone.')) {
            try {
                // In a real app, you would make an API call to delete the reel
                // const response = await ApiService.deleteReel(reelId);
                // if (response.success) {
                    // Remove the reel from the list
                    setReels(reels.filter(reel => reel.id !== reelId));
                    toast.success('Reel deleted successfully!');
                // } else {
                //     toast.error('Failed to delete reel: ' + response.message);
                // }
            } catch (error) {
                console.error('Delete error:', error);
                toast.error('Failed to delete reel: ' + error.message);
            }
        }
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                        <Link to="/studio/seller/upload" className="btn btn-success">
                            <i className="ri-add-line me-1"></i> Upload Reel
                        </Link>
                    </div>
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                <Link to="/studio/seller/upload" className="btn btn-success">
                                    <i className="ri-upload-line me-1"></i> Upload Reel
                                </Link>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Product Name</th>
                                            <th>Reel Count</th>
                                            <th>Title</th>
                                            <th>Category</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((productGroup) => (
                                            <tr key={productGroup.product}>
                                                <td>{productGroup.product}</td>
                                                <td>{productGroup.reelCount}</td>
                                                <td>{productGroup.title}{productGroup.reelCount > 1 ? ` (+${productGroup.reelCount - 1} more)` : ''}</td>
                                                <td>{productGroup.category || 'N/A'}</td>
                                                <td>{getStatusBadge(productGroup.status)}</td>
                                                <td>{productGroup.views}</td>
                                                <td>{productGroup.likes}</td>
                                                <td>{productGroup.date}</td>
                                                <td>
                                                    <button 
                                                        className="btn btn-sm btn-info me-1"
                                                        onClick={() => handleViewReelVideo(productGroup.reels[0].id)}
                                                        title="View Video Only"
                                                    >
                                                        <i className="ri-eye-line"></i> View
                                                    </button>
                                                    <button 
                                                        className="btn btn-sm btn-warning me-1"
                                                        onClick={() => handleEditReel(productGroup.reels[0].id)}
                                                        title="Edit"
                                                    >
                                                        <i className="ri-edit-line"></i> Edit
                                                    </button>
                                                    <button 
                                                        className="btn btn-sm btn-danger"
                                                        onClick={() => handleDeleteReel(productGroup.reels[0].id)}
                                                        title="Delete"
                                                    >
                                                        <i className="ri-delete-bin-line"></i> Delete
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Video Modal */}
            {showVideoModal && (
                <div className="modal fade show" style={{ display: 'block', backgroundColor: 'rgba(0,0,0,0.5)' }} tabIndex="-1">
                    <div className="modal-dialog modal-lg">
                        <div className="modal-content">
                            <div className="modal-header">
                                <h5 className="modal-title">Reel Videos for {viewingReel?.product}</h5>
                                <button 
                                    type="button" 
                                    className="btn-close" 
                                    onClick={() => setShowVideoModal(false)}
                                ></button>
                            </div>
                            <div className="modal-body">
                                {viewingReel && viewingReel.reels && (
                                    <div>
                                        <p><strong>Total Reels:</strong> {viewingReel.reelCount}</p>
                                        <div className="row">
                                            {viewingReel.reels.map((reel, index) => (
                                                <div className="col-md-12 mb-4" key={reel.id}>
                                                    <div className="card">
                                                        <div className="card-header">
                                                            <h6>{reel.title}</h6>
                                                        </div>
                                                        <div className="card-body">
                                                            <div className="ratio ratio-16x9">
                                                                <video 
                                                                    src="https://sample-videos.com/video123/mp4/720/big_buck_bunny_720p_1mb.mp4" 
                                                                    controls
                                                                    style={{ width: '100%', height: 'auto' }}
                                                                />
                                                            </div>
                                                            <div className="mt-2">
                                                                <p className="mb-1"><strong>Category:</strong> {reel.category}</p>
                                                                <p className="mb-1"><strong>Status:</strong> {getStatusBadge(reel.status)}</p>
                                                                <p className="mb-1"><strong>Views:</strong> {reel.views} | <strong>Likes:</strong> {reel.likes}</p>
                                                                <p className="mb-0"><strong>Date:</strong> {reel.date}</p>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                            <div className="modal-footer">
                                <button 
                                    type="button" 
                                    className="btn btn-secondary" 
                                    onClick={() => setShowVideoModal(false)}
                                >
                                    Close
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}
